const ONER_METHOD = 'Single-cell side-branch dilatation with BIOTRONIK Pantera LEO NC balloons at 14 atm after deployment at nominal pressure in a phantom bifurcation (3 samples per platform); cell opening = diameter of a circle fitted within the cell struts (Olympus SZX16 microscope).';
/** Öner 2021 Table 2: attained cell diameter = balloon diameter minus the published shortfall. */
const onerSB = (label, rows, avg) => [
  ...rows.map(([balloon, pct, diff]) =>
    bench(`${label}: cell opening ${(balloon - diff).toFixed(2)} mm after ${balloon.toFixed(2)} mm NC balloon (${pct}% / ${diff.toFixed(2)} mm below balloon diameter)`, +(balloon - diff).toFixed(2), 'mm', ONER_METHOD, `3.0 mm stent; ${balloon.toFixed(2)} mm balloon at 14 atm; value = balloon diameter minus the shortfall in Table 2`, ONER, D)),
  bench(`${label}: average shortfall of cell opening vs balloon diameter over 2.0–3.0 mm balloons ${avg}`, +avg.split(' ')[0], 'mm', ONER_METHOD, '3.0 mm stent; Table 2 / Results text', ONER),
  bench(`${label}: single-cell dilatation up to a 4.0 mm NC balloon tolerated (overexpansion benchmark; no strut fracture reported)`, 4.0, 'mm', ONER_METHOD, '3.0 mm stent; 4.0 mm balloon at 14 atm', ONER),
];
